// HasNextRun applies the HasEdge predicate on the "next_run" edge.
func HasNextRun() predicate.BillingPeriodicRealizationRun {
	return predicate.BillingPeriodicRealizationRun(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, false, NextRunTable, NextRunColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasNextRunWith applies the HasEdge predicate on the "next_run" edge with a given conditions (other predicates).
func HasNextRunWith(preds ...predicate.BillingPeriodicRealizationRun) predicate.BillingPeriodicRealizationRun {
	return predicate.BillingPeriodicRealizationRun(func(s *sql.Selector) {
		step := newNextRunStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

